#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <DHT.h>

// Temperature & Humidity Display
// Reads a DHT11/DHT22 and shows both values on a 16x2 I2C LCD.

const int DHT_PIN = 2;
const int DHT_TYPE = DHT11; // change to DHT22 if that's what you have

DHT dht(DHT_PIN, DHT_TYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  dht.begin();
  lcd.init();
  lcd.backlight();
}

void loop() {
  float humidity = dht.readHumidity();
  float tempC = dht.readTemperature();

  lcd.setCursor(0, 0);
  if (isnan(humidity) || isnan(tempC)) {
    lcd.print("Sensor error!   ");
  } else {
    lcd.print("Temp: ");
    lcd.print(tempC, 1);
    lcd.print((char)223); // degree symbol
    lcd.print("C ");
  }

  lcd.setCursor(0, 1);
  lcd.print("Humidity: ");
  lcd.print(humidity, 0);
  lcd.print("%  ");

  delay(2000); // DHT11/22 can only be read reliably about once every 1-2 seconds
}
